action.code:
# Let me process all files. First, I'll get details for each file to get creation dates
# I'll collect files that need renaming and those that need moving

files_to_process = []

# Get details for each file
for file_path in files_result:
    # Only process files, not directories (files have extensions)
    if '.' in file_path.split('/')[-1]:
        try:
            file_info = apis.file_system.show_file(file_path=file_path, access_token=access_token)
            files_to_process.append(file_info)
        except Exception as e:
            print(f"Error getting info for {file_path}: {e}")

print(f"Found {len(files_to_process)} files to process")
print("First 3 files with dates:")
for f in files_to_process[:3]:
    print(f"  {f['path']} - Created: {f['created_at']}")

