# Send reminders for all 15 payment requests that are 30+ days old
reminders_sent = []
reminders_failed = []

for req in old_requests:
    payment_request_id = req['payment_request_id']
    try:
        result = apis.venmo.remind_payment_request(
            payment_request_id=payment_request_id,
            access_token=token
        )
        reminders_sent.append({
            'payment_request_id': payment_request_id,
            'receiver': req['receiver']['name'],
            'result': result
        })
        print(f"✓ Reminder sent for request {payment_request_id} to {req['receiver']['name']}")
    except Exception as e:
        reminders_failed.append({
            'payment_request_id': payment_request_id,
            'receiver': req['receiver']['name'],
            'error': str(e)
        })
        print(f"✗ Failed to send reminder for request {payment_request_id}: {str(e)}")

print(f"\n\nSummary:")
print(f"Reminders sent: {len(reminders_sent)}")
