action.code:
all_playlist_songs = set()

for playlist in playlists_response['playlists']:
    playlist_songs = apis.spotify.get_playlist_songs(access_token=token, playlist_id=playlist['id'])
    print(f"Playlist {playlist['name']}: {playlist_songs}")

    if 'songs' in playlist_songs:
        for song in playlist_songs['songs']:
            all_playlist_songs.add(song['id'])

print(f"All playlist song IDs: {all_playlist_songs}")

# Get songs from all playlists
playlist_songs = set()
for playlist in all_playlists:
    playlist_id = playlist['id']
    page_index = 0
    while True:
        response = apis.spotify.get_playlist_songs(access_token=token, playlist_id=playlist_id, page_index=page_index)
        if not response.get('songs'):
            break
        for song in response['songs']:
            playlist_songs.add(song['id'])
        page_index += 1

print(f"Songs from playlists: {len(playlist_songs)}")

