# Get all liked songs (song library)
all_liked_songs = set()
page_index = 0
while True:
    result = apis.spotify.show_liked_songs(access_token=token, page_index=page_index, page_limit=20)
    if not result:
        break
    for song in result:
        all_liked_songs.add(song['song_id'])
    if len(result) < 20:
        break
    page_index += 1

print(f"Liked songs (song library): {len(all_liked_songs)} unique songs")

