            energy = features.get('energy', 0)
            danceability = features.get('danceability', 0)
            popularity = track.get('popularity', 0)

            if energy > 0.7 and danceability > 0.7:
                edm_tracks.append({
                    'title': track.get('name'),
                    'popularity': popularity,
                    'energy': energy,
                    'danceability': danceability
                })

print(f"Found {len(edm_tracks)} potential EDM tracks")

all_playlist_tracks = []
for playlist in all_playlists:
    page_index = 0
    while True:
        result = apis.spotify.get_playlist_tracks(access_token=token, playlist_id=playlist['id'], limit=50, page_index=page_index)
        if not result['items']:
            break
        all_playlist_tracks.extend(result['items'])
        page_index += 1

print(f"Total playlist tracks: {len(all_playlist_tracks)}")

